// Explainer engine: deterministic canvas runtime for narrated explainer videos.
// build.mjs inlines this file into player.html, followed by the job's scenes.js.
// Contract: every pixel and every sound event is a pure function of the time t (seconds).
// Do not edit this file per video. Write scenes.js against the API documented in
// references/engine-api.md.
"use strict";

const DATA = window.EXPLAINER;
const W = DATA.width, H = DATA.height, FPS = DATA.fps;
const DUR = DATA.dur;
const CUES = DATA.cues; // [{start, dur, text, words:[{w, t}]}]
const RENDER_MODE = /[?&]render\b/.test(location.search);

const canvas = document.getElementById("stage");
canvas.width = W; canvas.height = H;
const ctx = canvas.getContext("2d");

// ---------- math, easing, seeded randomness ----------
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, k) => a + (b - a) * k;
